#!/usr/bin/env python3
# ONSM Colab launcher. Embedded zlib payload expands to the full Python source.
# For an inspectable source file run: python onsm_fulltext_colab.py --extract
import zlib, base64, sys
PAYLOAD=''
raw=zlib.decompress(base64.b64decode(PAYLOAD))
if '--extract' in sys.argv:
    open('onsm_fulltext_source.py','wb').write(raw)
    print('Created onsm_fulltext_source.py')
else:
    exec(compile(raw.decode('utf-8'),'onsm_fulltext_source.py','exec'))
